class _UniffiConverterTypeAppView:

    @staticmethod
    def lift(value: int):
        return AppView._make_instance_(value)

    @staticmethod
    def check_lower(value: AppView):
        if not isinstance(value, AppView):
            raise TypeError("Expected AppView instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: AppViewProtocol):
        if not isinstance(value, AppView):
            raise TypeError("Expected AppView instance, {} found".format(type(value).__name__))
        return value._uniffi_clone_pointer()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer):
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw pointer value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: AppViewProtocol, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))



